1	//! Streaming recovery framing commitments. A digest is not a verified member.
2	//!
3	//! Inputs must already be acquired under caller authority and read budgets. This
4	//! layer bounds its own work, checks framing/order/local sizes and hashes bytes;
5	//! it does not check record signatures, copy-plan truth or publication readiness.
6	use atproto_dasl::Cid;
7	use sha2::{Digest, Sha256};
8	use std::{
9	    sync::{
10	        atomic::{AtomicBool, Ordering},
11	        Arc,
12	    },
13	    time::{Duration, Instant},
14	};
15	
16	const SAFE: u64 = 9_007_199_254_740_991;
17	const MAX_OBJECT: usize = 4 * 1024 * 1024;
18	type Result<T> = std::result::Result<T, Error>;
19	#[derive(Debug, thiserror::Error, PartialEq, Eq)]
20	pub enum Error {
21	    #[error("invalid recovery commitment framing: {0}")]
22	    Shape(&'static str),
23	    #[error("recovery commitment work budget exhausted")]
24	    Budget,
25	    #[error("recovery commitment cancelled")]
26	    Cancelled,
27	    #[error("recovery commitment builder previously failed")]
28	    Poisoned,
29	}
30	fn shape(ok: bool, reason: &'static str) -> Result<()> {
31	    if ok {
32	        Ok(())
33	    } else {
34	        Err(Error::Shape(reason))
35	    }
36	}
37	
38	/// Caller-selected work limits, not archive format size ceilings. Byte budget
39	/// counts framing and hashing work; candidate verification hashes bytes twice.
40	#[derive(Clone)]
41	pub struct Limits {
42	    pub items: u64,
43	    pub bytes: u64,
44	    pub duration: Duration,
45	    pub cancelled: Arc<AtomicBool>,
46	}
47	#[derive(Clone, Copy)]
48	pub struct Counts {
49	    pub membership: u64,
50	    pub records: u64,
51	    pub objects: u64,
52	}
53	#[derive(Clone, Copy)]
54	pub enum Domain {
55	    Member,
56	    Output,
57	}
58	pub struct Header<'a> {
59	    pub profile: u8,
60	    pub archive: [u8; 32],
61	    pub scope: [u8; 32],
62	    pub issuer: &'a str,
63	    pub plan: Option<&'a [u8]>,
64	}
65	struct Meter {
66	    limits: Limits,
67	    deadline: Instant,
68	    bytes: u64,
69	    items: u64,
70	}
71	impl Meter {
72	    fn new(limits: Limits, items: u64) -> Result<Self> {
73	        shape(
74	            !limits.duration.is_zero() && limits.duration <= Duration::from_secs(3600),
75	            "duration",
76	        )?;
77	        if items > limits.items {
78	            return Err(Error::Budget);
79	        }
80	        let deadline = Instant::now()
81	            .checked_add(limits.duration)
82	            .ok_or(Error::Budget)?;
83	        let out = Self {
84	            limits,
85	            deadline,
86	            bytes: 0,
87	            items: 0,
88	        };
89	        out.check()?;
90	        Ok(out)
91	    }
92	    fn check(&self) -> Result<()> {
93	        if self.limits.cancelled.load(Ordering::Relaxed) {
94	            return Err(Error::Cancelled);
95	        }
96	        if Instant::now() >= self.deadline {
97	            return Err(Error::Budget);
98	        }
99	        Ok(())
100	    }
101	    fn spend(&mut self, bytes: usize) -> Result<()> {
102	        self.check()?;
103	        self.bytes = self.bytes.checked_add(bytes as u64).ok_or(Error::Budget)?;
104	        if self.bytes > self.limits.bytes {
105	            return Err(Error::Budget);
106	        }
107	        Ok(())
108	    }
109	    fn item(&mut self) -> Result<()> {
110	        self.check()?;
111	        self.items = self.items.checked_add(1).ok_or(Error::Budget)?;
112	        if self.items > self.limits.items {
113	            return Err(Error::Budget);
114	        }
115	        Ok(())
116	    }
117	}
118	struct Core {
119	    hash: Sha256,
120	    meter: Meter,
121	    failed: bool,
122	}
123	impl Core {
124	    fn new(domain: &[u8], limits: Limits, items: u64) -> Result<Self> {
125	        let mut out = Self {
126	            hash: Sha256::new(),
127	            meter: Meter::new(limits, items)?,
128	            failed: false,
129	        };
130	        out.put(domain)?;
131	        Ok(out)
132	    }
133	    fn put(&mut self, bytes: &[u8]) -> Result<()> {
134	        self.meter.check()?;
135	        for part in bytes.chunks(64 * 1024) {
136	            self.meter.spend(part.len())?;
137	            self.hash.update(part)
138	        }
139	        Ok(())
140	    }
141	    fn n(&mut self, n: u64) -> Result<()> {
142	        self.put(&n.to_be_bytes())
143	    }
144	    fn frame(&mut self, b: &[u8]) -> Result<()> {
145	        self.n(b.len() as u64)?;
146	        self.put(b)
147	    }
148	    fn finish(self) -> Result<[u8; 32]> {
149	        if self.failed {
150	            return Err(Error::Poisoned);
151	        }
152	        self.meter.check()?;
153	        Ok(self.hash.finalize().into())
154	    }
155	}
156	fn raw_key(cid: &Cid) -> Result<(String, Vec<u8>)> {
157	    let raw = cid.to_bytes();
158	    shape(
159	        raw.len() == 36 && raw[..4] == [1, 0x55, 0x12, 0x20],
160	        "object CID",
161	    )?;
162	    Ok((cid.to_string(), raw))
163	}
164	fn ordered(last: &mut Option<String>, next: String) -> Result<()> {
165	    shape(
166	        last.as_ref().is_none_or(|old| old < &next),
167	        "duplicate or unordered CID",
168	    )?;
169	    *last = Some(next);
170	    Ok(())
171	}
172	#[derive(Clone, Copy, PartialEq, Eq)]
173	enum Phase {
174	    Membership,
175	    Records,
176	    Objects,
177	}
178	/// Strictly ordered streaming input. Any rejected operation poisons the builder,
179	/// so ignoring an error cannot produce a digest of a silently shortened member.
180	pub struct MemberFraming {
181	    core: Core,
182	    counts: Counts,
183	    phase: Phase,
184	    seen: u64,
185	    last: Option<String>,
186	}
187	impl MemberFraming {
188	    pub fn new(header: Header<'_>, counts: Counts, domain: Domain, limits: Limits) -> Result<Self> {
189	        shape(matches!(header.profile, 2 | 3), "profile")?;
190	        shape(
191	            !header.issuer.is_empty() && header.issuer.len() <= 80,
192	            "issuer length",
193	        )?;
194	        for count in [counts.membership, counts.records, counts.objects] {
195	            shape(count <= SAFE, "count")?
196	        }
197	        let total = counts
198	            .membership
199	            .checked_add(counts.records)
200	            .and_then(|n| n.checked_add(counts.objects))
201	            .ok_or(Error::Budget)?;
202	        if header.profile == 2 {
203	            shape(
204	                header.plan.is_none() && counts.membership == 0,
205	                "profile2 plan",
206	            )?
207	        } else {
208	            shape(
209	                header
210	                    .plan
211	                    .is_some_and(|p| !p.is_empty() && p.len() <= 4096),
212	                "profile3 plan",
213	            )?
214	        }
215	        let domain = match domain {
216	            Domain::Member => b"tools.kan.recovery.member.v1\0".as_slice(),
217	            Domain::Output => b"tools.kan.recovery.output.v1\0".as_slice(),
218	        };
219	        let mut core = Core::new(domain, limits, total)?;
220	        core.n(header.profile.into())?;
221	        core.frame(&header.archive)?;
222	        core.frame(&header.scope)?;
223	        core.frame(header.issuer.as_bytes())?;
224	        core.frame(b"plan")?;
225	        core.n(u64::from(header.plan.is_some()))?;
226	        if let Some(plan) = header.plan {
227	            core.frame(plan)?
228	        }
229	        core.frame(b"original-membership")?;
230	        core.n(counts.membership)?;
231	        Ok(Self {
232	            core,
233	            counts,
234	            phase: Phase::Membership,
235	            seen: 0,
236	            last: None,
237	        })
238	    }
239	    fn operation(&mut self, operation: impl FnOnce(&mut Self) -> Result<()>) -> Result<()> {
240	        if self.core.failed {
241	            return Err(Error::Poisoned);
242	        }
243	        self.core.failed = true;
244	        let result = operation(self);
245	        if result.is_ok() {
246	            self.core.failed = false
247	        }
248	        result
249	    }
250	    pub fn membership(&mut self, cid: &Cid, length: u64) -> Result<()> {
251	        self.operation(|s| {
252	            shape(
253	                s.phase == Phase::Membership && s.seen < s.counts.membership,
254	                "membership position",
255	            )?;
256	            shape(
257	                (1..=MAX_OBJECT as u64).contains(&length),
258	                "membership length",
259	            )?;
260	            let (name, key) = raw_key(cid)?;
261	            ordered(&mut s.last, name)?;
262	            s.core.meter.item()?;
263	            s.core.frame(&key)?;
264	            s.core.n(length)?;
265	            s.seen += 1;
266	            Ok(())
267	        })
268	    }
269	    pub fn begin_records(&mut self) -> Result<()> {
270	        self.operation(|s| {
271	            shape(
272	                s.phase == Phase::Membership && s.seen == s.counts.membership,
273	                "incomplete membership",
274	            )?;
275	            s.core.frame(b"records")?;
276	            s.core.n(s.counts.records)?;
277	            s.phase = Phase::Records;
278	            s.seen = 0;
279	            s.last = None;
280	            Ok(())
281	        })
282	    }
283	    pub fn record(
284	        &mut self,
285	        sequence: u64,
286	        manifest: &[u8],
287	        receipt: &[u8],
288	        proof: &[u8],
289	    ) -> Result<()> {
290	        self.operation(|s| {
291	            shape(
292	                s.phase == Phase::Records && s.seen < s.counts.records && sequence == s.seen + 1,
293	                "record position",
294	            )?;
295	            for (bytes, max) in [(manifest, 65536), (receipt, 65536), (proof, 16384)] {
296	                shape(!bytes.is_empty() && bytes.len() <= max, "record bytes")?
297	            }
298	            s.core.meter.item()?;
299	            s.core.n(sequence)?;
300	            s.core.frame(manifest)?;
301	            s.core.frame(receipt)?;
302	            s.core.frame(proof)?;
303	            s.seen += 1;
304	            Ok(())
305	        })
306	    }
307	    pub fn begin_objects(&mut self) -> Result<()> {
308	        self.operation(|s| {
309	            shape(
310	                s.phase == Phase::Records && s.seen == s.counts.records,
311	                "incomplete records",
312	            )?;
313	            s.core.frame(b"original-objects")?;
314	            s.core.n(s.counts.objects)?;
315	            s.phase = Phase::Objects;
316	            s.seen = 0;
317	            s.last = None;
318	            Ok(())
319	        })
320	    }
321	    pub fn original_object(&mut self, cid: &Cid, bytes: &[u8]) -> Result<()> {
322	        self.operation(|s| {
323	            shape(
324	                s.phase == Phase::Objects && s.seen < s.counts.objects,
325	                "object position",
326	            )?;
327	            shape(bytes.len() <= MAX_OBJECT, "object bytes")?;
328	            let (name, key) = raw_key(cid)?;
329	            ordered(&mut s.last, name)?;
330	            s.core.meter.item()?;
331	            s.core.frame(&key)?;
332	            s.core.n(bytes.len() as u64)?;
333	            s.core.frame(bytes)?;
334	            s.seen += 1;
335	            Ok(())
336	        })
337	    }
338	    pub fn finish(self) -> Result<[u8; 32]> {
339	        if self.core.failed {
340	            return Err(Error::Poisoned);
341	        }
342	        shape(
343	            self.phase == Phase::Objects && self.seen == self.counts.objects,
344	            "incomplete objects",
345	        )?;
346	        self.core.finish()
347	    }
348	}
349	/// R1 framing also verifies candidate content addresses. It still does not prove
350	/// candidate membership, historical selection or a restoration observation.
351	pub struct RestorationFraming {
352	    core: Core,
353	    count: u64,
354	    seen: u64,
355	    last: Option<String>,
356	}
357	impl RestorationFraming {
358	    pub fn new(count: u64, limits: Limits) -> Result<Self> {
359	        shape(count <= SAFE, "count")?;
360	        let mut core = Core::new(b"tools.kan.recovery.restorations.v1\0", limits, count)?;
361	        core.n(count)?;
362	        Ok(Self {
363	            core,
364	            count,
365	            seen: 0,
366	            last: None,
367	        })
368	    }
369	    pub fn candidate(&mut self, cid: &Cid, bytes: &[u8]) -> Result<()> {
370	        if self.core.failed {
371	            return Err(Error::Poisoned);
372	        }
373	        self.core.failed = true;
374	        shape(self.seen < self.count, "candidate position")?;
375	        shape(
376	            !bytes.is_empty() && bytes.len() <= MAX_OBJECT,
377	            "candidate bytes",
378	        )?;
379	        let (name, key) = raw_key(cid)?;
380	        ordered(&mut self.last, name)?;
381	        self.core.meter.item()?;
382	        let mut hash = Sha256::new();
383	        for part in bytes.chunks(64 * 1024) {
384	            self.core.meter.spend(part.len())?;
385	            hash.update(part)
386	        }
387	        let actual: [u8; 32] = hash.finalize().into();
388	        shape(actual == key[4..], "candidate hash")?;
389	        self.core.frame(&key)?;
390	        self.core.n(bytes.len() as u64)?;
391	        self.core.frame(bytes)?;
392	        self.seen += 1;
393	        self.core.failed = false;
394	        Ok(())
395	    }
396	    pub fn finish(self) -> Result<[u8; 32]> {
397	        if self.core.failed {
398	            return Err(Error::Poisoned);
399	        }
400	        shape(self.seen == self.count, "incomplete candidates")?;
401	        self.core.finish()
402	    }
403	}
