fn review_pb1_python_generated_probes_match_named_rust_outcomes() {
    let f = fixture();
    let ctx = context(&f["context"]);
    let chain = chain(&f, &ctx);
    let path = std::env::var("REVIEW_PROBES").expect("REVIEW_PROBES");
